(function(){
  'use strict';

  const AI=()=>window.D365_AI;
  const fr=()=>document.documentElement.lang==='fr';
  const tr=(en,frText)=>fr()?frText:en;
  const e=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const d=()=>typeof data==='function'?data():{};
  const todayIso=()=>typeof today==='function'?today():new Date().toISOString().slice(0,10);
  const streams=()=>typeof allStreams==='function'?allStreams():[...(state.framework?.valueStreams||[]),...(state.framework?.crossFunctional||[])];
  const streamDef=id=>streams().find(s=>s.id===id)||{id,name:id,bpo:'',l2:[]};
  const regs=()=>state.registers||(state.registers={});
  const taskArr=()=>{state.tasks=state.tasks||{};return state.tasks.tasks||(state.tasks.tasks=[])};
  const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const entityScope=()=>window.D365_ENTITY_MODEL?.getContext?.()||'All entities';

  function activeGuideStream(){return document.querySelector('[data-v13-guide-stream].active')?.dataset.v13GuideStream||selectedStream||'M2O';}
  function guideLens(stream,l2){
    const btn=[...document.querySelectorAll('.v14-guide-detail [data-jump-l2]')].find(b=>b.dataset.jumpL2===`${stream}|${l2}`),row=btn?.closest('tr'),cells=row?[...row.querySelectorAll('td')]:[];
    return {area:cells[1]?.innerText.trim()||'',design:cells[2]?.innerText.trim()||'',data:cells[3]?.innerText.trim()||'',test:cells[4]?.innerText.trim()||''};
  }
  function relevant(stream,l2){return AI()?.streamContext?AI().streamContext(stream,l2):{stream,name:streamDef(stream).name,bpo:streamDef(stream).bpo,l2,findings:[],requirements:[],decisions:[],tasks:[],tests:[],data:[],workshops:[]};}
  function openItems(xs,closed=['Closed','Resolved','Decided','Approved','Passed','Signed off']){return (xs||[]).filter(x=>!closed.includes(x.status));}

  function l2Options(stream,current=''){return (streamDef(stream).l2||[]).map(x=>`<option value="${e(x)}" ${x===current?'selected':''}>${e(x)}</option>`).join('');}
  function streamOptions(current){return streams().map(s=>`<option value="${e(s.id)}" ${s.id===current?'selected':''}>${e(s.id)} · ${e(s.name)}</option>`).join('');}
  function modeBadge(){return AI()?.endpoint?.()?tr('Secure AI available','IA sécurisée disponible'):tr('Local assisted mode','Mode assisté local');}

  function specialQuestions(stream,l2){
    const n=norm(l2),q=[];
    if(/price|pricing|agreement|quote|rfq/.test(n))q.push(tr('What is the authoritative price source, hierarchy, effective-date logic and approval rule for an exception?','Quelle est la source autoritaire du prix, la hiérarchie, la logique de date d’effet et la règle d’approbation d’une exception?'));
    if(/bom|route|formula|production|machine|labor|cost/.test(n))q.push(tr('Which product/version/resource decisions must be fixed before production can execute and cost correctly?','Quelles décisions produit/version/ressource doivent être fixées avant que la production puisse s’exécuter et se coûter correctement?'));
    if(/plan|forecast|mrp|capacity|supply/.test(n))q.push(tr('Which demand, supply, inventory and capacity parameters drive the planning result, and who owns each parameter?','Quels paramètres de demande, offre, inventaire et capacité pilotent le résultat de planification, et qui possède chacun?'));
    if(/warehouse|pick|pack|ship|receive|inventory|replenish/.test(n))q.push(tr('What physical event proves the transaction occurred, and what identifier/location/status must be captured at that point?','Quel événement physique prouve que la transaction a eu lieu, et quel identifiant/emplacement/statut doit être capturé à ce moment?'));
    if(/quality|inspection|sampling|non conformity|non-conformance/.test(n))q.push(tr('What condition triggers inspection or blocking, what is sampled, who can disposition the result, and what traceability must remain?','Quelle condition déclenche inspection ou blocage, qu’est-ce qui est échantillonné, qui peut disposer du résultat et quelle traçabilité doit demeurer?'));
    if(/invoice|pay|purchase|supplier|vendor|matching/.test(n))q.push(tr('What approval, receipt and matching evidence is required before the financial liability can be paid?','Quelle preuve d’approbation, réception et rapprochement est requise avant que la dette puisse être payée?'));
    if(/gl|ledger|account|close|allocation|reconcil|financial/.test(n))q.push(tr('What subledger event creates the accounting entry, how is it reconciled, and what manual posting should be prevented?','Quel événement sous-livre crée l’écriture comptable, comment est-elle rapprochée, et quelle écriture manuelle doit être empêchée?'));
    if(/master|data|creation|maintenance|governance/.test(n))q.push(tr('Who owns create/change approval, what makes the record valid, and what duplicate/inactive conditions must be prevented?','Qui possède l’approbation création/changement, qu’est-ce qui rend l’enregistrement valide et quels doublons/inactifs doivent être empêchés?'));
    if(!q.length)q.push(tr('What is the future-state business outcome, where does D365 become the system of record, and which exceptions require a formal decision?','Quel est le résultat d’affaires cible, où D365 devient-il le système autoritaire, et quelles exceptions exigent une décision formelle?'));
    return q;
  }

  function localAgenda(stream,l2){
    const c=relevant(stream,l2),lens=guideLens(stream,l2),find=openItems(c.findings,['Closed','Resolved']).slice(0,5),req=openItems(c.requirements,['Closed','Approved']).slice(0,5),dec=openItems(c.decisions,['Closed','Decided']).slice(0,5),tasks=openItems(c.tasks,['Closed','Approved']).slice(0,5),wr=c.workshops?.find(x=>x.l2===l2),questions=[...specialQuestions(stream,l2),tr('Which variants are legitimate by legal entity, customer/product family or site, and which differences should be eliminated?','Quelles variantes sont légitimes par entité, client/famille produit ou site, et quelles différences devraient être éliminées?'),tr('Which control must be preventive in D365 versus detective after the fact?','Quel contrôle doit être préventif dans D365 plutôt que détectif après coup?'),tr('What evidence will prove this capability is ready to sign off?','Quelle preuve démontrera que cette capacité est prête à être approuvée?')];
    return {mode:'local',title:`${stream} · ${l2} — ${tr('workshop agenda','ordre du jour atelier')}`,summary:tr('Use the workshop to leave with decisions, requirements, data actions and testable acceptance evidence—not only discussion notes.','Utilisez l’atelier pour sortir avec des décisions, exigences, actions données et preuves d’acceptation testables — pas seulement des notes de discussion.'),sections:[
      {heading:tr('Objective','Objectif'),items:[lens.design||tr(`Agree the future-state design for ${l2}, the D365 boundary, ownership, controls and unresolved decisions.`,`Convenir de la conception cible pour ${l2}, de la frontière D365, des responsabilités, contrôles et décisions non résolues.`)]},
      {heading:tr('Bring into the room','À apporter en atelier'),items:[find.length?`${find.length} ${tr('open finding(s)','constat(s) ouvert(s)')}`:tr('No linked open findings currently recorded','Aucun constat ouvert lié actuellement'),req.length?`${req.length} ${tr('open requirement(s)','exigence(s) ouverte(s)')}`:tr('No linked open requirements currently recorded','Aucune exigence ouverte liée actuellement'),dec.length?`${dec.length} ${tr('open decision(s)','décision(s) ouverte(s)')}`:tr('No linked open decisions currently recorded','Aucune décision ouverte liée actuellement'),wr?`${tr('Workshop status','Statut atelier')}: ${wr.status}`:tr('Workshop readiness record not started','Enregistrement de préparation atelier non démarré')]},
      {heading:tr('Design questions','Questions de conception'),items:questions},
      {heading:tr('Data to review','Données à revoir'),items:[lens.data||tr('Identify the master/configuration/open-transaction data this capability needs, the owner, quality rule, source and cutover treatment.','Identifier les données maîtres/configuration/transactions ouvertes nécessaires, leur responsable, règle qualité, source et traitement de bascule.'),...c.data.slice(0,4).map(x=>`${x.id} · ${x.object||''} · ${x.quality||'TBD'} · ${x.mappingStatus||'Not Started'} / ${x.cleansingStatus||'Not Started'}`)]},
      {heading:tr('Decisions to leave with','Décisions à obtenir'),items:[tr('Future-state process and D365 system boundary.','Processus cible et frontière système D365.'),tr('Configuration / policy choices and legitimate variants.','Choix de configuration/politique et variantes légitimes.'),tr('Data owner, cleanup rule and migration treatment.','Responsable données, règle de nettoyage et traitement migration.'),tr('Control / approval design and any required escalation.','Conception contrôle/approbation et toute escalade requise.')]},
      {heading:tr('Expected outputs','Livrables attendus'),items:[tr('Updated L2 workshop status and notes.','Statut et notes atelier L2 mis à jour.'),tr('New/updated requirements and formal decisions.','Exigences et décisions formelles nouvelles/mises à jour.'),tr('Execution tasks with owner, dates and estimated hours.','Tâches d’exécution avec responsable, dates et heures estimées.'),tr('Minimum SIT/UAT scenarios and sign-off evidence.','Scénarios SIT/UAT minimaux et preuve d’approbation.')]},
      {heading:tr('Existing execution context','Contexte d’exécution existant'),items:tasks.length?tasks.map(x=>`${x.id} · ${x.title} · ${x.status}`):[tr('No linked execution tasks yet.','Aucune tâche d’exécution liée pour le moment.')]}]};
  }

  function renderDoc(x){return `<div class="v19-doc"><div class="v19-doc-head"><span>${e(x.mode==='remote'?tr('AI-generated draft','Brouillon généré par IA'):tr('Assisted draft','Brouillon assisté'))}</span><h3>${e(x.title||'')}</h3><p>${e(x.summary||'')}</p></div><div class="v19-doc-grid">${(x.sections||[]).map(s=>`<section><h4>${e(s.heading||'')}</h4><ul>${(s.items||[]).filter(Boolean).map(i=>`<li>${e(typeof i==='string'?i:i.text||'')}</li>`).join('')}</ul></section>`).join('')}</div></div>`;}
  function normalizeDoc(remote,fallback){if(remote?.sections?.length)return {...remote,mode:'remote'};return fallback;}

  async function openAgenda(stream,l2){
    const local=()=>localAgenda(stream,l2),m=modal(tr('Prepare BPO workshop','Préparer atelier BPO'),`<div class="v19-loading">${tr('Preparing workshop package…','Préparation du dossier atelier…')}</div>`),body=m.querySelector('.modal-body');
    const result=await (AI()?.request?.('workshop_agenda',{stream,l2,context:relevant(stream,l2)},local)||local()),doc=normalizeDoc(result,local());body.innerHTML=`${renderDoc(doc)}<div class="v19-task-create"><h4>${tr('Optional execution action','Action d’exécution optionnelle')}</h4><div class="form-grid"><label>${tr('Owner','Responsable')}<input name="owner" value="${e(streamDef(stream).bpo||'')}"></label><label>${tr('Due','Échéance')}<input type="date" name="due"></label><label>${tr('Estimated hours','Heures estimées')}<input type="number" min="0" step="0.5" name="hours"></label></div></div>`;m.querySelector('.modal-save').textContent=tr('Create preparation task','Créer tâche de préparation');m.querySelector('.modal-save').onclick=()=>{const owner=m.querySelector('[name="owner"]').value.trim(),due=m.querySelector('[name="due"]').value,hours=Number(m.querySelector('[name="hours"]').value)||0,t={id:uid('AI-WKS'),title:tr(`Prepare workshop: ${l2}`,`Préparer atelier : ${l2}`),stream,l1:stream,l2,sourceLevel:'L2',sourceType:'AI-assisted workshop',sourceId:`AI-WKS|${stream}|${l2}|${Date.now()}`,sourceTitle:l2,milestoneId:'M-02',type:'Workshop / Design',owner:owner||streamDef(stream).bpo||'',priority:'High',status:'Not Started',progress:0,start:todayIso(),due,forecastDue:due,estimatedHours:hours||'',expectedOutcome:doc.summary||'',entityScope:entityScope(),notes:(doc.sections||[]).map(s=>`${s.heading}: ${(s.items||[]).join(' | ')}`).join('\n')};taskArr().push(t);mark('tasks');m.remove();render();};
  }

  function splitNotes(text){return String(text||'').split(/\n+|(?<=[.!?])\s+/).map(x=>x.replace(/^[-•*\d.)\s]+/,'').trim()).filter(x=>x.length>8);}
  function localExtract(text,stream,l2){
    const out=[];splitNotes(text).forEach(line=>{const n=norm(line);let type='',raidType='Risk';
      if(/\b(decided|decision|agreed|approved|selected|choose|chose|will use|retenu|décidé|convenu|approuvé)\b/.test(n))type='Decision';
      else if(/\b(issue|blocked|cannot|failed|problem|enjeu|bloqué|impossible|problème)\b/.test(n)){type='RAID';raidType='Issue'}
      else if(/\b(depend|waiting for|requires .* before|dependency|dépend|attend|prérequis)\b/.test(n)){type='RAID';raidType='Dependency'}
      else if(/\b(risk|may|might|could|concern|uncertain|risque|pourrait|préoccupation|incertain)\b/.test(n)){type='RAID';raidType='Risk'}
      else if(/\b(must|shall|system should|system must|requirement|needs to|doit|devra|exigence|besoin de)\b/.test(n))type='Requirement';
      else if(/\b(action|follow up|prepare|validate|review|confirm|clean|map|test|assign|complete|analyze|analyse|préparer|valider|revoir|confirmer|nettoyer|mapper|tester|assigner|compléter)\b/.test(n))type='Task';
      if(!type)return;const due=(line.match(/\b20\d{2}-\d{2}-\d{2}\b/)||[])[0]||'',owner=(line.match(/(?:owner|responsable)\s*[:=-]\s*([^,;]+)/i)||[])[1]?.trim()||'';out.push({type,title:line,stream,l2,owner,due,raidType,severity:'Medium',selected:true});
    });
    const seen=new Set();return {mode:'local',proposals:out.filter(x=>{const k=x.type+'|'+norm(x.title);if(seen.has(k))return false;seen.add(k);return true;}).slice(0,30)};
  }
  function proposalsHtml(ps){return `<div class="v19-proposals"><div class="notice"><b>${tr('Human approval required.','Approbation humaine requise.')}</b> ${tr('Nothing below is written to the Control Tower until you select and approve it. Edit the classification/text before saving.','Rien ci-dessous n’est écrit dans le Control Tower avant votre sélection et approbation. Modifiez classification/texte avant sauvegarde.')}</div>${ps.length?ps.map((p,i)=>`<div class="v19-proposal" data-v19-proposal="${i}"><label class="v19-proposal-check"><input type="checkbox" data-pick ${p.selected!==false?'checked':''}></label><select data-type>${['Task','Decision','Requirement','RAID'].map(x=>`<option ${x===p.type?'selected':''}>${x}</option>`).join('')}</select><textarea data-title rows="2">${e(p.title)}</textarea><input data-owner placeholder="${tr('Owner','Responsable')}" value="${e(p.owner||'')}"><input data-due type="date" value="${e(p.due||'')}"><select data-raid-type>${['Risk','Assumption','Issue','Dependency'].map(x=>`<option ${x===(p.raidType||'Risk')?'selected':''}>${x}</option>`).join('')}</select></div>`).join(''):`<div class="empty">${tr('No action/decision/requirement/RAID statement was confidently detected. Add more explicit wording or use the secure AI backend for richer extraction.','Aucun énoncé action/décision/exigence/RAID n’a été détecté avec confiance. Ajoutez une formulation plus explicite ou utilisez le backend IA sécurisé pour une extraction plus riche.')}</div>`}</div>`;}
  function addProposal(p,stream,l2,source){
    const title=p.title.trim();if(!title)return false;const sourceId=`AI-MTG|${Date.now()}|${Math.random().toString(36).slice(2,7)}`;
    if(p.type==='Task'){const arr=taskArr();if(arr.some(x=>norm(x.title)===norm(title)&&x.stream===stream))return false;arr.push({id:uid('AI-T'),title,stream,l1:stream,l2,sourceLevel:l2?'L2':'L1',sourceType:'AI-assisted meeting notes',sourceId,sourceTitle:tr('Meeting notes','Notes de réunion'),milestoneId:'M-02',type:'Activity',owner:p.owner||streamDef(stream).bpo||'',priority:'Medium',status:'Not Started',progress:0,start:todayIso(),due:p.due||'',forecastDue:p.due||'',entityScope:entityScope(),notes:source.slice(0,1000)});return 'tasks';}
    if(p.type==='Decision'){const arr=regs().decisions||(regs().decisions=[]);if(arr.some(x=>norm(x.title)===norm(title)&&x.stream===stream))return false;arr.push({id:uid('DEC'),category:'Solution design',title,stream,l2,owner:p.owner||'Business Owner',due:p.due||'',status:'Open',background:tr('Proposed from reviewed meeting notes.','Proposé à partir de notes de réunion révisées.'),sourceType:'AI-assisted meeting notes',sourceId,entityScope:entityScope()});return 'registers';}
    if(p.type==='Requirement'){const arr=regs().requirements||(regs().requirements=[]);if(arr.some(x=>norm(x.title)===norm(title)&&x.stream===stream))return false;arr.push({id:uid('REQ'),stream,l2,title,owner:p.owner||streamDef(stream).bpo||'',status:'Draft',fitGap:'TBD',sourceType:'AI-assisted meeting notes',sourceId,entityScope:entityScope()});return 'registers';}
    const arr=regs().raid||(regs().raid=[]);if(arr.some(x=>norm(x.title||x.description)===norm(title)&&x.stream===stream))return false;arr.push({id:uid('RAID'),type:p.raidType||'Risk',severity:p.severity||'Medium',stream,title,owner:p.owner||streamDef(stream).bpo||'',due:p.due||'',status:'Open',probability:'Medium',impact:'Medium',sourceType:'AI-assisted meeting notes',sourceId,entityScope:entityScope()});return 'registers';
  }

  function openMeetingNotes(defaultStream=selectedStream||'O2C',defaultL2=''){
    let stream=defaultStream,l2=defaultL2;const m=modal(tr('Meeting notes → Control Tower proposals','Notes de réunion → propositions Control Tower'),`<div class="v19-meeting"><div class="form-grid"><label>${tr('Value stream','Chaîne de valeur')}<select id="v19MeetStream">${streamOptions(stream)}</select></label><label>L2<select id="v19MeetL2"><option value="">${tr('Stream level','Niveau chaîne')}</option>${l2Options(stream,l2)}</select></label><label class="full">${tr('Paste meeting notes / transcript excerpt','Collez notes de réunion / extrait de transcription')}<textarea id="v19MeetNotes" rows="10" placeholder="${tr('Paste notes here. Clear statements such as “Decision: …”, “Risk: …”, “Action: …” and “System must …” improve local extraction.','Collez les notes ici. Des énoncés clairs comme « Décision : … », « Risque : … », « Action : … » et « Le système doit… » améliorent l’extraction locale.')}"></textarea></label></div><div class="v19-meet-actions"><span>${e(modeBadge())}</span><button type="button" class="btn primary" id="v19AnalyzeNotes">${tr('Analyze notes','Analyser les notes')}</button></div><div id="v19ProposalArea"></div></div>`);
    m.querySelector('.modal-save').style.display='none';const ss=m.querySelector('#v19MeetStream'),ls=m.querySelector('#v19MeetL2');ss.onchange=()=>{stream=ss.value;ls.innerHTML=`<option value="">${tr('Stream level','Niveau chaîne')}</option>${l2Options(stream,'')}`};ls.onchange=()=>l2=ls.value;
    m.querySelector('#v19AnalyzeNotes').onclick=async()=>{const text=m.querySelector('#v19MeetNotes').value.trim();if(!text)return;stream=ss.value;l2=ls.value;const area=m.querySelector('#v19ProposalArea');area.innerHTML=`<div class="v19-loading">${tr('Analyzing notes…','Analyse des notes…')}</div>`;const local=()=>localExtract(text,stream,l2),r=await (AI()?.request?.('meeting_notes',{stream,l2,text,context:relevant(stream,l2)},local)||local()),ps=Array.isArray(r?.proposals)?r.proposals:local().proposals;area.innerHTML=proposalsHtml(ps);if(!ps.length)return;const save=m.querySelector('.modal-save');save.style.display='';save.textContent=tr('Add selected proposals','Ajouter propositions sélectionnées');save.onclick=()=>{let t=false,rgs=false,added=0;area.querySelectorAll('.v19-proposal').forEach(row=>{if(!row.querySelector('[data-pick]').checked)return;const p={type:row.querySelector('[data-type]').value,title:row.querySelector('[data-title]').value,owner:row.querySelector('[data-owner]').value,due:row.querySelector('[data-due]').value,raidType:row.querySelector('[data-raid-type]').value,severity:'Medium'},k=addProposal(p,stream,l2,text);if(k==='tasks')t=true;if(k==='registers')rgs=true;if(k)added++;});if(t)mark('tasks');if(rgs)mark('registers');m.remove();render();if(!added)alert(tr('No new records were added; selected proposals were blank or duplicates.','Aucun nouvel enregistrement ajouté; les propositions sélectionnées étaient vides ou en doublon.'));};};
  }

  function testScenarioTexts(stream,l2){
    const n=norm(l2),base=[tr(`Happy path: execute ${l2} end-to-end with valid master data and expected approvals.`,`Parcours normal : exécuter ${l2} bout en bout avec données maîtres valides et approbations attendues.`),tr(`Exception path: execute ${l2} with an invalid/missing condition and confirm D365 blocks, routes or records the exception correctly.`,`Parcours exception : exécuter ${l2} avec une condition invalide/manquante et confirmer que D365 bloque, route ou enregistre correctement l’exception.`),tr(`Control path: attempt ${l2} with an unauthorized role or outside the approval rule and confirm the control evidence.`,`Parcours contrôle : tenter ${l2} avec un rôle non autorisé ou hors règle d’approbation et confirmer la preuve de contrôle.`),tr(`Reconciliation path: complete ${l2} and reconcile the resulting operational/accounting/inventory state to the expected source evidence.`,`Parcours rapprochement : compléter ${l2} et rapprocher l’état opérationnel/comptable/inventaire résultant à la preuve source attendue.`)];
    if(/price|quote|agreement/.test(n))base.push(tr('Boundary test: expired/effective-dated or quantity-break pricing must select the correct commercial condition and require approval for override.','Test de frontière : le prix expiré/daté ou par palier doit sélectionner la bonne condition commerciale et exiger une approbation pour dérogation.'));
    if(/bom|route|production|machine|labor/.test(n))base.push(tr('Manufacturing test: use the approved BOM/route/resource version, report actual consumption/output and verify expected WIP/variance behavior.','Test manufacturier : utiliser la version BOM/route/ressource approuvée, déclarer consommation/sortie réelle et vérifier WIP/écarts attendus.'));
    if(/warehouse|pick|pack|ship|receive/.test(n))base.push(tr('Warehouse exception: short/over receipt or pick, quality hold and wrong location/UOM must follow the designed exception path.','Exception entrepôt : réception/cueillette courte ou excédentaire, blocage qualité et mauvais emplacement/UdeM doivent suivre le traitement prévu.'));
    if(/quality|inspection|sampling/.test(n))base.push(tr('Quality failure: failed sample/inspection must create the designed block/disposition/non-conformance evidence and prevent unintended use.','Échec qualité : échantillon/inspection échoué doit créer le blocage/disposition/non-conformité prévu et empêcher l’utilisation non voulue.'));
    if(/pay|invoice|purchase|supplier/.test(n))base.push(tr('Procure-to-pay exception: invoice quantity/price outside tolerance or missing receipt must be held until the defined approval/evidence exists.','Exception source-to-pay : facture quantité/prix hors tolérance ou réception manquante doit être bloquée jusqu’à la preuve/approbation définie.'));
    if(/gl|ledger|close|reconcil|financial|account/.test(n))base.push(tr('Accounting test: verify subledger posting, dimensions/control account, reversal/settlement and reconciliation to GL.','Test comptable : vérifier comptabilisation sous-livre, dimensions/compte de contrôle, renversement/règlement et rapprochement au GL.'));
    return [...new Set(base)];
  }
  async function openTestGenerator(stream,l2){
    const local=()=>({mode:'local',scenarios:testScenarioTexts(stream,l2)}),m=modal(tr('Generate test scenarios','Générer scénarios de test'),`<div class="v19-loading">${tr('Building test scenarios…','Construction des scénarios de test…')}</div>`),r=await (AI()?.request?.('test_scenarios',{stream,l2,context:relevant(stream,l2)},local)||local()),sc=Array.isArray(r?.scenarios)?r.scenarios:local().scenarios;m.querySelector('.modal-body').innerHTML=`<div class="form-grid"><label>${tr('Test type','Type de test')}<select id="v19TestType"><option>SIT</option><option>UAT</option></select></label><label>${tr('Owner','Responsable')}<input id="v19TestOwner" value="${e(streamDef(stream).bpo||'')}"></label></div><div class="v19-check-list">${sc.map((x,i)=>`<label><input type="checkbox" data-v19-test="${i}" checked><span>${e(typeof x==='string'?x:x.scenario||x.text||'')}</span></label>`).join('')}</div><div class="notice">${tr('Review wording and deselect scenarios that do not represent the intended design. Tests are created as Not Started; execution evidence still requires human completion.','Revoyez la formulation et désélectionnez les scénarios qui ne représentent pas la conception prévue. Les tests sont créés Non démarrés; la preuve d’exécution exige toujours une complétion humaine.')}</div>`;m.querySelector('.modal-save').textContent=tr('Add selected tests','Ajouter tests sélectionnés');m.querySelector('.modal-save').onclick=()=>{const arr=regs().testScenarios||(regs().testScenarios=[]),type=m.querySelector('#v19TestType').value,owner=m.querySelector('#v19TestOwner').value.trim();m.querySelectorAll('[data-v19-test]').forEach(cb=>{if(!cb.checked)return;const raw=sc[Number(cb.dataset.v19Test)],scenario=typeof raw==='string'?raw:raw.scenario||raw.text||'';if(!scenario||arr.some(x=>norm(x.scenario)===norm(scenario)&&x.stream===stream&&x.l2===l2&&x.testType===type))return;arr.push({id:uid('TEST'),testType:type,scenario,entityScope:entityScope(),stream,l2,l3ProcessId:'',criticality:'High',owner:owner||streamDef(stream).bpo||'',linkedRequirement:'',status:'Not Started',defectId:'',evidence:'',sourceType:'AI-assisted test design'});});mark('registers');m.remove();render();};
  }

  function cleanupChecks(stream,l2){
    const n=norm(l2),checks=[tr('Confirm future-state owner and system of record for each field/object.','Confirmer le responsable cible et le système autoritaire pour chaque champ/objet.'),tr('Identify duplicates, inactive/obsolete records and conflicting identifiers.','Identifier doublons, enregistrements inactifs/obsolètes et identifiants conflictuels.'),tr('Validate mandatory fields, valid values/reference data and legal-entity scope.','Valider champs obligatoires, valeurs/référentiels valides et portée entité.'),tr('Reconcile units of measure, currencies, effective dates and status values where applicable.','Rapprocher unités de mesure, devises, dates d’effet et statuts lorsque pertinent.'),tr('Define source-to-D365 mapping, transformation rule and reject/error handling.','Définir mapping source-D365, règle de transformation et traitement rejet/erreur.'),tr('Define cutover population: migrate, configure, open transaction, balance or archive.','Définir population de bascule : migrer, configurer, transaction ouverte, solde ou archiver.'),tr('Create a reconciliation/control proving the loaded population is complete and accurate.','Créer un rapprochement/contrôle prouvant que la population chargée est complète et exacte.')];
    if(/customer|price|quote|agreement/.test(n))checks.push(tr('Check customer/item/UOM mappings, overlapping/expired prices, effective dates and duplicate commercial conditions.','Vérifier mappings client/article/UdeM, prix chevauchants/expirés, dates d’effet et conditions commerciales en doublon.'));
    if(/supplier|vendor|purchase|pay/.test(n))checks.push(tr('Validate legal/tax identity, active status, vendor-item/UOM/lead time and independently validate payment/bank instructions.','Valider identité légale/fiscale, statut actif, fournisseur-article/UdeM/délai et valider indépendamment instructions bancaires/paiement.'));
    if(/bom|route|production|material|machine|labor|cost/.test(n))checks.push(tr('Check BOM/route version overlap, orphan/inactive components, UOM conversions, yields/scrap, resource references and cost-category mappings.','Vérifier chevauchement versions BOM/route, composants orphelins/inactifs, conversions UdeM, rendements/rebuts, références ressources et mappings catégories coût.'));
    if(/warehouse|inventory|pick|pack|receive/.test(n))checks.push(tr('Physically reconcile on-hand by item/site/warehouse/location/batch/status/license plate and resolve negative/unidentified stock.','Rapprocher physiquement stock par article/site/entrepôt/emplacement/lot/statut/license plate et résoudre stock négatif/non identifié.'));
    if(/quality|inspection|sampling/.test(n))checks.push(tr('Validate specifications, test methods, sampling quantities, effective versions, disposition codes and item/vendor/customer associations.','Valider spécifications, méthodes de test, quantités d’échantillonnage, versions d’effet, codes disposition et associations article/fournisseur/client.'));
    if(/gl|ledger|financial|account|close/.test(n))checks.push(tr('Reconcile chart/dimensions/open balances to subledgers and eliminate invalid/manual control-account mappings.','Rapprocher plan de comptes/dimensions/soldes ouverts aux sous-livres et éliminer mappings invalides/manuels des comptes de contrôle.'));
    return [...new Set(checks)];
  }
  async function openCleanup(stream,l2){
    const local=()=>({mode:'local',checks:cleanupChecks(stream,l2)}),m=modal(tr('Data cleanup assistant','Assistant nettoyage des données'),`<div class="v19-loading">${tr('Building cleanup checklist…','Construction de la checklist de nettoyage…')}</div>`),r=await (AI()?.request?.('data_cleanup',{stream,l2,context:relevant(stream,l2)},local)||local()),checks=Array.isArray(r?.checks)?r.checks:local().checks;m.querySelector('.modal-body').innerHTML=`<div class="v19-check-list static">${checks.map(x=>`<label><input type="checkbox" checked><span>${e(typeof x==='string'?x:x.text||'')}</span></label>`).join('')}</div><div class="v19-task-create"><h4>${tr('Create data-readiness action','Créer action de préparation données')}</h4><div class="form-grid"><label>${tr('Owner','Responsable')}<input name="owner" value="${e(streamDef(stream).bpo||'')}"></label><label>${tr('Due','Échéance')}<input type="date" name="due"></label><label>${tr('Estimated hours','Heures estimées')}<input type="number" min="0" step="0.5" name="hours"></label></div></div>`;m.querySelector('.modal-save').textContent=tr('Create cleanup task','Créer tâche nettoyage');m.querySelector('.modal-save').onclick=()=>{const selected=[...m.querySelectorAll('.v19-check-list input:checked')].map(x=>x.closest('label').innerText.trim()),owner=m.querySelector('[name="owner"]').value.trim(),due=m.querySelector('[name="due"]').value,hours=Number(m.querySelector('[name="hours"]').value)||0;if(!selected.length){alert(tr('Select at least one cleanup check.','Sélectionnez au moins un contrôle de nettoyage.'));return;}taskArr().push({id:uid('AI-DATA'),title:tr(`Data readiness: ${l2}`,`Préparation données : ${l2}`),stream,l1:stream,l2,sourceLevel:'L2',sourceType:'AI-assisted data cleanup',sourceId:`AI-DATA|${stream}|${l2}|${Date.now()}`,sourceTitle:l2,milestoneId:'M-04',type:'Data',owner:owner||streamDef(stream).bpo||'',priority:'High',status:'Not Started',progress:0,start:todayIso(),due,forecastDue:due,estimatedHours:hours||'',expectedOutcome:tr('Profile, cleanse, map and reconcile the data required for this capability.','Profiler, nettoyer, mapper et rapprocher les données requises pour cette capacité.'),entityScope:entityScope(),notes:selected.map(x=>'• '+x).join('\n')});mark('tasks');m.remove();render();};
  }

  function challengeQuestions(req){
    const fit=req.fitGap||'TBD',qs=[tr('What business outcome is mandatory, independent of the legacy method?','Quel résultat d’affaires est obligatoire, indépendamment de la méthode legacy?'),tr('Which standard D365 capability/configuration was tested against this outcome, and what specifically failed?','Quelle capacité/configuration D365 standard a été testée contre ce résultat, et qu’est-ce qui a précisément échoué?'),tr('Could a process change, policy change, workflow, reporting solution or integration meet the outcome without an extension?','Un changement de processus/politique, workflow, rapport ou intégration pourrait-il répondre au résultat sans extension?'),tr('What volume/frequency/user population makes the gap material?','Quel volume/fréquence/population utilisateur rend l’écart important?'),tr('What control, regulatory, customer or financial requirement prevents the standard option?','Quelle exigence de contrôle, réglementaire, client ou financière empêche l’option standard?'),tr('What is the implementation, testing, upgrade and support cost of the proposed gap solution?','Quel est le coût d’implantation, test, mise à niveau et support de la solution d’écart proposée?'),tr('What is the acceptable fallback if the gap is deferred from go-live?','Quel est le fallback acceptable si l’écart est reporté après go-live?')];
    if(fit==='Integration')qs.unshift(tr('Which system truly owns this data/process, and why should the boundary remain outside D365?','Quel système possède réellement ces données/processus, et pourquoi la frontière devrait-elle demeurer hors D365?'));
    if(fit==='Reporting / Analytics')qs.unshift(tr('Is the need transactional/operational in D365, or can the outcome be delivered through governed analytics without changing the transaction model?','Le besoin est-il transactionnel/opérationnel dans D365, ou le résultat peut-il être livré par l’analytique gouvernée sans changer le modèle transactionnel?'));
    if(fit==='Process change')qs.unshift(tr('Is the requested legacy behavior a true business requirement or a habit that should be retired?','Le comportement legacy demandé est-il une vraie exigence d’affaires ou une habitude à retirer?'));
    return qs;
  }
  async function openFitGap(stream,l2){
    const rs=(d().requirements||[]).filter(x=>x.stream===stream&&(!l2||!x.l2||x.l2===l2)&&!['Closed','Deferred'].includes(x.status));if(!rs.length){alert(tr('No open requirements are available for this stream/L2.','Aucune exigence ouverte n’est disponible pour cette chaîne/L2.'));return;}
    const m=modal(tr('Fit/Gap challenger','Challengeur Fit/Gap'),`<div class="form-grid"><label class="full">${tr('Requirement','Exigence')}<select id="v19Req">${rs.map(x=>`<option value="${e(x.id)}">${e(x.id)} · ${e(x.fitGap||'TBD')} · ${e(x.title)}</option>`).join('')}</select></label></div><div id="v19Challenge"></div>`),sel=m.querySelector('#v19Req'),area=m.querySelector('#v19Challenge');
    const show=async()=>{const req=rs.find(x=>x.id===sel.value)||rs[0],local=()=>({mode:'local',questions:challengeQuestions(req)});area.innerHTML=`<div class="v19-loading">${tr('Challenging the proposed fit/gap…','Challenge du fit/gap proposé…')}</div>`;const r=await (AI()?.request?.('fit_gap_challenge',{stream,l2,requirement:req,context:relevant(stream,l2)},local)||local()),qs=Array.isArray(r?.questions)?r.questions:local().questions;area.innerHTML=`<div class="v19-challenge-head"><b>${e(req.fitGap||'TBD')}</b><span>${e(req.title)}</span></div><ol class="v19-challenge-list">${qs.map(x=>`<li>${e(typeof x==='string'?x:x.text||'')}</li>`).join('')}</ol><div class="notice">${tr('The challenger does not change the fit/gap classification. Its purpose is to make the evidence for non-standard design explicit before approval.','Le challengeur ne change pas la classification fit/gap. Son but est de rendre explicite la preuve d’une conception non standard avant approbation.')}</div>`;m.dataset.req=req.id;m.dataset.questions=JSON.stringify(qs);};sel.onchange=show;await show();m.querySelector('.modal-save').textContent=tr('Create decision package','Créer dossier décision');m.querySelector('.modal-save').onclick=()=>{const req=rs.find(x=>x.id===m.dataset.req);if(!req)return;const arr=regs().decisions||(regs().decisions=[]),id=uid('DEC'),qs=JSON.parse(m.dataset.questions||'[]');arr.push({id,category:'Solution design',title:tr(`Fit/Gap decision: ${req.title}`,`Décision Fit/Gap : ${req.title}`),stream,l2:req.l2||l2,owner:'Business Owner',status:'Analysis',linkedRequirement:req.id,background:tr(`Requirement ${req.id} is currently classified ${req.fitGap||'TBD'}. Review alternatives and evidence before approving a non-standard solution.`,`L’exigence ${req.id} est actuellement classifiée ${req.fitGap||'TBD'}. Revoir les alternatives et preuves avant d’approuver une solution non standard.`),options:tr('Standard configuration / process change / reporting / integration / extension / defer','Configuration standard / changement processus / reporting / intégration / extension / reporter'),recommendation:'',supportingEvidence:qs.map(x=>'• '+(typeof x==='string'?x:x.text||'')).join('\n'),sourceType:'AI-assisted fit/gap challenger',entityScope:entityScope()});mark('registers');m.remove();render();setTimeout(()=>{if(typeof editDecision==='function')editDecision(id)},0);};
  }

  function workbenchHtml(stream){const s=streamDef(stream),first=s.l2?.[0]||'';return `<section class="v19-workbench card"><div class="v19-wb-head"><div><span>${tr('AI-ASSISTED WORK','TRAVAIL ASSISTÉ PAR IA')}</span><h2>${tr('BPO design workbench','Atelier de conception BPO')}</h2><p>${tr('Generate drafts and proposals from the live project context. Nothing is approved or written automatically; BPO/SME review remains mandatory.','Générez brouillons et propositions à partir du contexte projet actif. Rien n’est approuvé ou écrit automatiquement; la révision BPO/SME demeure obligatoire.')}</p></div><div class="v19-mode"><b>${e(modeBadge())}</b><small>${tr('Human-in-the-loop','Humain dans la boucle')}</small></div></div><div class="v19-wb-select"><label>L2 / ${tr('Capability','Capacité')}<select id="v19L2Select">${l2Options(stream,first)}</select></label></div><div class="v19-tools"><button type="button" data-v19-tool="agenda">${tr('Prepare workshop agenda','Préparer ordre du jour')}</button><button type="button" data-v19-tool="notes">${tr('Meeting notes → proposals','Notes → propositions')}</button><button type="button" data-v19-tool="tests">${tr('Generate test scenarios','Générer scénarios de test')}</button><button type="button" data-v19-tool="data">${tr('Data cleanup checklist','Checklist nettoyage données')}</button><button type="button" data-v19-tool="fitgap">${tr('Challenge Fit/Gap','Challenger Fit/Gap')}</button></div></section>`;}
  function bindWorkbench(root,stream){const sel=root.querySelector('#v19L2Select');root.querySelectorAll('[data-v19-tool]').forEach(b=>b.onclick=()=>{const l2=sel?.value||'';if(b.dataset.v19Tool==='agenda')openAgenda(stream,l2);if(b.dataset.v19Tool==='notes')openMeetingNotes(stream,l2);if(b.dataset.v19Tool==='tests')openTestGenerator(stream,l2);if(b.dataset.v19Tool==='data')openCleanup(stream,l2);if(b.dataset.v19Tool==='fitgap')openFitGap(stream,l2);});}
  function decorateGuide(){const app=document.querySelector('#app');if(!app||app.querySelector('.v19-workbench'))return;const hero=app.querySelector('.v13-guide-hero');if(!hero)return;const stream=activeGuideStream(),target=app.querySelector('.v15-workshop')||app.querySelector('.v14-guide-detail')||hero;target.insertAdjacentHTML('afterend',workbenchHtml(stream));bindWorkbench(app.querySelector('.v19-workbench'),stream);}
  function decorateCockpit(){const a=document.querySelector('.v18-ai-actions');if(!a||a.querySelector('#v19MeetingGlobal'))return;a.insertAdjacentHTML('beforeend',`<button class="btn tiny" type="button" id="v19MeetingGlobal">${tr('Meeting notes → proposals','Notes → propositions')}</button>`);a.querySelector('#v19MeetingGlobal').onclick=()=>openMeetingNotes(selectedStream||'O2C','');}
  function decorateStream(){const a=document.querySelector('.v18-coach-actions');if(!a||a.querySelector('[data-v19-stream-workbench]'))return;a.insertAdjacentHTML('beforeend',`<button type="button" class="btn" data-v19-stream-workbench="${e(selectedStream)}">${tr('AI workbench','Atelier IA')}</button>`);a.querySelector('[data-v19-stream-workbench]').onclick=()=>{const stream=selectedStream,s=streamDef(stream),m=modal(`${stream} — ${tr('BPO design workbench','Atelier de conception BPO')}`,`<div class="v19-modal-workbench">${workbenchHtml(stream)}</div>`);m.querySelector('.modal-save').textContent=tr('Close','Fermer');m.querySelector('.modal-save').onclick=()=>m.remove();bindWorkbench(m.querySelector('.v19-workbench'),stream);};}

  function decorate(){if(view==='d365guide')decorateGuide();if(view==='cockpit')decorateCockpit();if(view==='streams')decorateStream();}
  const baseRender=render;render=function(){baseRender();decorate();};
  try{decorate()}catch(err){console.warn('[V19] AI-assisted work',err)}

  window.D365_AI_WORKBENCH={openAgenda,openMeetingNotes,openTestGenerator,openCleanup,openFitGap,localAgenda,localExtract,testScenarioTexts,cleanupChecks,challengeQuestions};
})();
